def valid_path_brute(n, edges, source, destination):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    visited = [False] * n
    stack = [source]
    visited[source] = True
    while stack:
        node = stack.pop()
        if node == destination:
            return True
        for nxt in adj[node]:
            if not visited[nxt]:
                visited[nxt] = True
                stack.append(nxt)
    return False

